.inspector-header h2 { margin: 0; font-size: 18px; line-height: 26px; font-weight: 500; }
.inspector-body { min-height: 0; overflow: auto; padding: 24px; font-size: 14px; line-height: 22px; }
.workspace-description { max-width: 760px; margin: 0 0 16px; color: var(--muted); font-size: 12px; line-height: 20px; }
.workspace-intro { max-width: 760px; margin: 0 0 20px; }
.workspace-intro h3 { margin: 0 0 8px; font-size: 20px; line-height: 28px; font-weight: 500; }
.workspace-intro p { max-width: 620px; margin: 0; color: var(--muted); font-size: 13px; line-height: 21px; }
.eyebrow { color: var(--muted); font-size: 10px; line-height: 14px; letter-spacing: .08em; }
.icon-button { display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 8px; background: none; color: var(--muted); font-size: 18px; }
.icon-button:hover { background: var(--color-background-secondary-ghost-hover); }
.workspace-tabs { display: flex; gap: 20px; margin-bottom: 20px; overflow-x: auto; border-bottom: 1px solid var(--color-border-subtle); }
.workspace-tabs button { flex: none; min-height: 40px; padding: 8px 0; border-bottom: 2px solid transparent; color: var(--muted); font-size: 14px; line-height: 20px; white-space: nowrap; }
.workspace-tabs button.active { border-color: var(--color-text); color: var(--color-text); font-weight: var(--font-weight-strong); }
.quest-workspace { display: grid; grid-template-columns: 272px minmax(0,1fr); gap: 24px; }
.quest-list { min-width: 0; padding-right: 16px; border-right: 1px solid var(--color-border-subtle); }
.quest-detail { min-width: 0; max-width: 760px; }
.quest-list .list-row > span:first-child { min-width: 0; flex: 1; }
.quest-list .list-row small { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.quest-list .list-row > .state-label { flex: none; padding-top: 2px; font-size: 12px; line-height: 18px; }
.quest-empty { padding: 8px 0 16px; color: var(--color-text-secondary); font-size: 13px; line-height: 20px; }
.quest-empty p { margin: 0 0 8px; }
