interface QuestProject { key: string; name: string; path: string; quests: WorkspaceQuest[]; loaded: number }
const nonempty = (value: unknown): string => typeof value === "string" ? value.trim() : "";
const directoryName = (path: string): string => path.replace(/[\\/]+$/, "").split(/[\\/]/).pop() || "";
function projectFor(quest: WorkspaceQuest, workspaceId: string, workspaceRoot: string, workspaceName: string): Omit<QuestProject, "quests" | "loaded"> {
  const metadata = quest.metadata || {};
  const project = metadata.project && typeof metadata.project === "object" && !Array.isArray(metadata.project) ? metadata.project as Row : {};
  const projectId = nonempty(quest.project_id) || nonempty(metadata.project_id) || nonempty(project.id);
  const explicitRoot = nonempty(quest.project_root) || nonempty(metadata.project_root) || nonempty(project.root);
  const explicitWorkspaceId = nonempty(quest.workspace_id) || nonempty(metadata.workspace_id);
  const explicitWorkspaceRoot = nonempty(quest.workspace_root) || nonempty(metadata.workspace_root);
  const path = explicitRoot || explicitWorkspaceRoot || (!projectId && (!explicitWorkspaceId || explicitWorkspaceId === workspaceId) ? workspaceRoot : "");
  const name = nonempty(quest.project_name) || nonempty(metadata.project_name) || nonempty(project.name) || directoryName(path) || projectId || explicitWorkspaceId || workspaceName || "当前工作空间";
  return { key: projectId ? `project:${projectId}` : explicitRoot ? `root:${explicitRoot}` : explicitWorkspaceId ? `workspace:${explicitWorkspaceId}` : explicitWorkspaceRoot ? `root:${explicitWorkspaceRoot}` : `workspace:${workspaceId || workspaceRoot || "current"}`, name, path };
}

function QuestGroupDisclosure({ open, id, children }: { open: boolean; id: string; children: ReactNode }) {
  const panel = useRef<HTMLDivElement>(null);
  const initial = useRef(open);
  const previous = useRef(open);
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !open);
    if (previous.current === open) return;
    previous.current = open;
    const finish = () => { element.style.height = open ? "auto" : "0px"; element.style.opacity = open ? "1" : "0"; };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = open ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = open ? "1" : "0";
      timeout = window.setTimeout(finish, 200);
    });
    const transitioned = (event: TransitionEvent) => { if (event.target === element && event.propertyName === "height") finish(); };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [open]);
  return <div ref={panel} id={id} className="quest-group-content" aria-hidden={!open} style={{ height: initial.current ? "auto" : "0px", opacity: initial.current ? 1 : 0 }}>{children}</div>;
}

function QuestProjectGroup({ project, selectedId, search, filter, onSelect }: { project: QuestProject; selectedId: string; search: string; filter: QuestFilter; onSelect: (id: string) => void }) {
  const [expanded, setExpanded] = useState(true);
